def load(path: Path):
    with path.open(encoding="utf-8") as f:
        return json.load(f, object_pairs_hook=OrderedDict)


def flatten(node, prefix=""):
    out: dict[str, str] = {}
    for key, value in node.items():
        full = f"{prefix}.{key}" if prefix else key
        if isinstance(value, dict):
            out.update(flatten(value, full))
        else:
            out[full] = value
    return out


def translate_tree(node, idx: int, path: str, missing: list[str]):
    result = OrderedDict()
    for key, value in node.items():
        full = f"{path}.{key}" if path else key
        if isinstance(value, dict):
            result[key] = translate_tree(value, idx, full, missing)
        else:
            if full in OVERRIDES:
                result[key] = OVERRIDES[full][idx]
            elif value in T:
                result[key] = T[value][idx]
            else:
                result[key] = value
                missing.append(full)
    return result


def main() -> int:
    check_only = "--check" in sys.argv
    de = load(MESSAGES / "de.json")
    flat_de = flatten(de)

    had_problem = False
    for i, locale in enumerate(LOCALES):
        missing: list[str] = []
        tree = translate_tree(de, i, "", missing)
        # Nur echte fehlende Übersetzungen zählen (Marken dürfen identisch bleiben).
        real_missing = [k for k in missing if flat_de[k] not in BRAND_KEEP]
        flat_new = flatten(tree)
        identical = sum(
            1
            for k, v in flat_de.items()
            if isinstance(v, str) and flat_new.get(k) == v
        )
        status = "ok" if not real_missing else f"MISSING {len(real_missing)}"
        print(f"{locale}: keys={len(flat_new)} identical_to_de={identical} {status}")
        if real_missing:
            had_problem = True
            for k in real_missing[:40]:
                print(f"    · {k}: {flat_de[k]!r}")
        if not check_only:
            out = MESSAGES / f"{locale}.json"
            with out.open("w", encoding="utf-8") as f:
                json.dump(tree, f, ensure_ascii=False, indent=2)
                f.write("\n")

    return 1 if (check_only and had_problem) else 0


if __name__ == "__main__":
    raise SystemExit(main())
